describe("refreshPrices", () => {
  const makeLines = (): CartLine[] => [
    { product: { id: "p1", name: "Widget", unitPriceCents: 1000 }, quantity: 2 },
    { product: { id: "p2", name: "Gadget", unitPriceCents: 2000 }, quantity: 1 },
  ];

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1100)
        .mockResolvedValueOnce(1900),
    };
    const result = await refreshPrices(makeLines(), fetcher);
    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(1100);
    expect(result[1]!.product.unitPriceCents).toBe(1900);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves product fields other than unitPriceCents", async () => {
    const lines: CartLine[] = [
      {
        product: { id: "p1", name: "Widget", unitPriceCents: 1000, weightGrams: 500, currency: "EUR" },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.name).toBe("Widget");
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-100),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network")),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow("network");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";

const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2500, weightGrams: 300 };

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  describe("add", () => {
    it("adds a new product", () => {
      cart.add(widget, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product again", () => {
      cart.add(widget, 2);
      cart.add(widget, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      expect(() => cart.add(widget, 0)).toThrow(RangeError);
      expect(() => cart.add(widget, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
      expect(() => cart.add(bad, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      cart.add(widget, 1);
      expect(cart.remove(widget.id)).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      cart.add(widget, 2);
      cart.updateQuantity(widget.id, 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      cart.add(widget, 2);
      cart.updateQuantity(widget.id, 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove(widget.id)).toBe(false); // already gone
    });

    it("throws for unknown product", () => {
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      cart.add(widget, 1);
      expect(() => cart.updateQuantity(widget.id, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      cart.add(widget, 1);
      expect(() => cart.updateQuantity(widget.id, 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      cart.add(widget, 2);
      cart.add(gadget, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copies that do not affect cart state", () => {
      cart.add(widget, 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      expect(cart.itemCount).toBe(2);
    });
  });
});

describe("Cart — pricing pipeline", () => {
  it("computes correct totals with defaults (no discount, no tax, free shipping)", () => {
    const cart = new Cart();
    cart.add(widget, 3); // 3 * 1000 = 3000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3000);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(3000);
  });

  it("returns all-zero totals for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount → tax on discounted subtotal → shipping pipeline", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };

    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
      region: "US-CA",
    });
    cart.add(widget, 2); // subtotal = 2000

    const totals = cart.totals();

    // Discount called with subtotal
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(2000);
    // Tax called with discounted subtotal (2000 - 200 = 1800) and region
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1800, "US-CA");
    // Shipping called with lines and discounted subtotal
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1800,
    );

    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(200);
    expect(totals.taxCents).toBe(80);
    expect(totals.shippingCents).toBe(500);
    // total = discountedSubtotal + tax + shipping = 1800 + 80 + 500
    expect(totals.totalCents).toBe(2380);
  });

  it("clamps negative discount to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(widget, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps over-subtotal discount to subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(widget, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0); // all discounted, no tax/shipping on 0
  });

  it("clamps negative tax to 0", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults region to US", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(widget, 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("sums multiple products in subtotal", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 1); // 2500
    expect(cart.totals().subtotalCents).toBe(4500);
  });
});

describe("Cart — async checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("w1");
  });

  describe("price refresh", () => {
    it("uses refreshed prices in totals", async () => {
      const cart = new Cart();
      cart.add(widget, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(1200);
      expect(result.totals.subtotalCents).toBe(2400); // 1200 * 2
    });

    it("propagates price fetch failure", async () => {
      const cart = new Cart();
      cart.add(widget, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
    });
  });

  describe("inventory check", () => {
    it("passes when inventory is available", async () => {
      const cart = new Cart();
      cart.add(widget, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("w1", 2);
    });

    it("throws InventoryError when item unavailable", async () => {
      const cart = new Cart();
      cart.add(widget, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "sold out",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("w1");
        expect(invErr.requested).toBe(2);
        expect(invErr.message).toBe("sold out");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(widget, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("w1");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(3);
      }
    });

    it("uses default message when reason is not provided", async () => {
      const cart = new Cart();
      cart.add(widget, 3);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 1,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.message).toContain("insufficient stock");
        expect(invErr.message).toContain("w1");
      }
    });

    it("checks first failing item only (first denial wins)", async () => {
      const cart = new Cart();
      cart.add(widget, 1);
      cart.add(gadget, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: false, reason: "no stock" })
          .mockResolvedValueOnce({ available: true }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        // Second product never checked because first failed
        expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
      }
    });
  });

  describe("async tax provider", () => {
    it("uses async tax rate in totals computation", async () => {
      const cart = new Cart({
        region: "US-CA",
      });
      cart.add(widget, 2); // subtotal = 2000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(2000 * 0.1) = 200
      expect(result.totals.taxCents).toBe(200);
      expect(result.totals.totalCents).toBe(2200);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies discount before async tax", async () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        region: "US",
      });
      cart.add(widget, 2); // subtotal = 2000, discount = 500, discountedSubtotal = 1500

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(1500 * 0.1) = 150
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(150);
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(widget, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("refreshes prices, checks inventory, computes async tax + shipping", async () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };

      const cart = new Cart({
        discountPolicy: mockDiscount,
        shippingCalculator: mockShipping,
        region: "FR",
      });
      cart.add(widget, 2); // original subtotal = 2000

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1100),
